import FreeCAD

# Open the saved document
doc = FreeCAD.open("/home/user/Unnamed.FCStd")

print("Document opened successfully!")
print("Document name:", doc.Name)

# List all objects in the document
print("\nObjects in document:")
for obj in doc.Objects:
    print(f"  - {obj.Name}: {obj.TypeId}")

# Check for the Body
body = None
for obj in doc.Objects:
    if "Body" in obj.Name or "PartDesign" in obj.TypeId:
        print(f"\nFound Part Design object: {obj.Name} ({obj.TypeId})")
        if "Body" in obj.TypeId:
            body = obj

if body:
    print(f"\nBody contents:")
    # Get the features in the body
    try:
        features = body.getFeatures()
        for f in features:
            print(f"  - {f.Name}: {f.TypeId}")
    except Exception as e:
        print(f"Error getting features: {e}")

# Check the ShapeBinder
for obj in doc.Objects:
    if "ShapeBinder" in obj.TypeId:
        binder = obj
        print(f"\nShapeBinder found: {binder.Name}")
        if hasattr(binder, 'Shape'):
            shape = binder.Shape
            print(f"  Shape type: {shape.ShapeType}")
            print(f"  Volume: {shape.Volume}")

            # Verify it's a solid
            if shape.ShapeType == "Solid":
                print("  ✓ This is a valid Solid")
            else:
                print("  ✗ This is NOT a Solid")

# Recompute to ensure everything is valid
try:
    doc.recompute()
    print("\nRecompute successful!")
except Exception as e:
    print(f"\nRecompute error: {e}")

FreeCAD.closeDocument(doc.Name)
print("\nVerification complete!")
EOF
